insert into public.recipes (id, status, cover_image, prep_minutes, cook_minutes, servings, video_url, family_id, variant_label, variant_image, related_post_ids) values ('recipe-ogorki-malosolne-ostre', 'published', 'https://kdrbtwwhmzszzukcffsu.supabase.co/storage/v1/object/public/recipe-media/recipes/recipe-ogorki-malosolne-ostre/8d85b2d6-3204-4897-95c8-75f9582aba02.webp', 20, 0, 6, null, 'family-ogorki-malosolne', '{"de":"Scharf","pl":"ostre"}'::jsonb, 'https://kdrbtwwhmzszzukcffsu.supabase.co/storage/v1/object/public/recipe-media/recipes/recipe-ogorki-malosolne-ostre/8d85b2d6-3204-4897-95c8-75f9582aba02.webp', array['post-kiszenie', 'post-ferment-glaeser', 'post-polenladen', 'post-ersatzprodukte-de']::text[]) on conflict (id) do update set status = excluded.status, cover_image = excluded.cover_image, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes, servings = excluded.servings, video_url = excluded.video_url, family_id = excluded.family_id, variant_label = excluded.variant_label, variant_image = excluded.variant_image, related_post_ids = excluded.related_post_ids, updated_at = now();
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-ogorki-malosolne-ostre', 'de', 'Ogórki małosolne scharf', 'scharf', 'Die scharfe Linie nutzt dieselbe milde 2-Prozent-Lake wie die klassischen Ogórki małosolne, bringt aber mit frischen Chilischoten und einem Stück Meerrettich spürbare Schärfe in die kurze Gärzeit, ganz ohne einen Tropfen Essig.', '[{"text":"Frische, feste Gurken waschen und die Enden anschneiden, dann mit Knoblauch, Dill, ein bis zwei längs eingeschnittenen frischen Chilischoten und einem Stück Meerrettichwurzel in ein großes Glas schichten.","tip":"Das ist derselbe kurze Ferment wie bei der [klassischen Version](/de/rezepte/ogorki-malosolne/klassisch), nur die Würze ändert sich, mit den echten [Ogórki kiszone](/de/rezepte/ogorki-kiszone) oder den essiggesäuerten [Ogórki konserwowe](/de/rezepte/ogorki-konserwowe) hat das nichts zu tun."},{"text":"Für die Lake 1 Liter kaltes Wasser mit 20 g unjodiertem Salz verrühren, das entspricht etwa 2 Prozent, die Gurken damit vollständig bedecken und bei 18 bis 22 Grad 24 bis 48 Stunden stehen lassen, bevor du zum ersten Mal kostest.","tip":"Chili und Meerrettich machen die Lake schneller aromatisch, an der Salzmenge selbst ändert sich dabei nichts, mehr zur Technik erklärt der [Kiszenie-Guide](/de/blog/kiszenie-guide)."},{"text":"Danach in den Kühlschrank stellen und innerhalb von zwei bis vier Tagen aufessen, am besten zu Grillwurst und frischem Brot, bei Schimmel oder fauligem Geruch gehört das ganze Glas in den Müll.","tip":"Wer es milder mag, findet die Linie mit [Honig](/de/rezepte/ogorki-malosolne/honig), für mehr Biss sorgt die Linie mit [Eichenblatt](/de/rezepte/ogorki-malosolne/eichenblatt), frische Chilischoten gibt es im Supermarkt, Meerrettichwurzel oft günstiger im [Polenladen](/de/blog/polenladen-einkaufen)."}]'::jsonb, 'Ogórki małosolne scharf, die scharfe Linie der Małosolne, mit frischen Chilischoten und Meerrettich in derselben milden Lake. Die scharfe Linie der [Ogórki małosolne](/de/rezepte/ogorki-malosolne) übernimmt die komplette Technik der klassischen Version, nur Chili und ein Stück Meerrettich kommen als Würze mit ins Glas. Historisch war Meerrettich in Kleinpolen und im Süden Polens ohnehin fester Bestandteil vieler Kiszonki, weil seine Schärfe und seine Gerbstoffe Fäulniskeimen entgegenwirken und den Gurken zugleich einen kräftigeren, erdigeren Ton geben, frische Chilischoten sind dagegen ein jüngerer Zusatz, der erst mit der breiteren Verfügbarkeit von Chili in polnischen Supermärkten in die Hausrezepte einzog. Anders als bei den essiggesäuerten [Ogórki konserwowe](/de/rezepte/ogorki-konserwowe) trägt hier weiterhin ausschließlich die Milchsäuregärung die Säure, Chili verändert nur den Geschmack, nicht die zugrunde liegende Technik oder die Haltbarkeitslogik. Wie bei der Grundversion bleibt das Zeitfenster kurz, ein bis drei Tage bei Zimmertemperatur, denn genau dieses kurze Fenster unterscheidet die Małosolne von den lange gegorenen [Ogórki kiszone](/de/rezepte/ogorki-kiszone).

## Einkaufen und kochen

Kaufe dieselben festen, frischen kleinen Gurken wie für die klassische Version, dazu ein bis zwei frische Chilischoten, ein Stück Meerrettichwurzel, Knoblauch und Dill. Frische Chilischoten gibt es meist günstig im Supermarkt, unjodiertes Salz und Meerrettichwurzel oft zuverlässiger im [Polenladen](/de/blog/polenladen-einkaufen).

Die 2-prozentige Lake bleibt exakt wie bei der klassischen Version, denn Chili verändert die Milchsäuregärung selbst nicht, es liefert nur Capsaicin für die Schärfe, keine zusätzliche Säure oder Haltbarkeit. Die längs eingeschnittenen Chilischoten geben ihre Schärfe schneller an die Lake ab als ganze Schoten, deshalb schmeckt diese Linie oft schon nach 24 Stunden deutlich würziger als die milde Grundversion. Wie immer müssen die Gurken vollständig unter der Lake bleiben, und sobald sie nach einer leichten, runden Säure mit spürbarer Schärfe schmecken, gehören sie in den Kühlschrank, sonst kippt auch diese Linie langsam Richtung kräftigerer Kiszone.

In Deutschland lässt sich diese Linie genauso schnell ansetzen wie die klassische Version, sobald im Sommer frische kleine Gurken und Chili im Supermarkt oder im [Polenladen](/de/blog/polenladen-einkaufen) liegen. Kinder dürfen beim Schichten von Knoblauch und Dill helfen, das Einschneiden der Chilischoten und das Ansetzen der Lake bleibt bei den Erwachsenen. Fehlt Meerrettichwurzel, hilft der Überblick zu [Ersatzprodukten](/de/blog/ersatzprodukte-de).

## Am Tisch

Serviere die scharfen Gurken zu Grillwurst oder deftigem Aufschnitt, ihre Schärfe passt gut zu fettigem Fleisch vom Grill. Wer es milder mag, findet die Linie mit [Honig](/de/rezepte/ogorki-malosolne/honig), die klassische Version bleibt bei den [Ogórki małosolne klassisch](/de/rezepte/ogorki-malosolne/klassisch).

Zu viel Chili auf einmal macht die Lake unangenehm brennend statt angenehm scharf, hier lohnt sich Zurückhaltung und ein Nachwürzen erst beim zweiten Glas. Die Salzmenge trotz Chili zu erhöhen ist unnötig, denn die Schärfe kommt vom Capsaicin und nicht vom Salz. Und wer diese Linie mit den essiggesäuerten [Ogórki konserwowe](/de/rezepte/ogorki-konserwowe) verwechselt, erwartet die falsche Haltbarkeit und den falschen Säuregrad.

Wer die Schärfe noch weiter steigern will, nimmt zwei statt einer Chilischote oder lässt die Kerne drin, wer es lieber rund und süß mag, wechselt zur Linie mit [Honig](/de/rezepte/ogorki-malosolne/honig) oder zur besonders knackigen Linie mit [Eichenblatt](/de/rezepte/ogorki-malosolne/eichenblatt). Alle drei teilen sich die klassische Basis bei den [Ogórki małosolne](/de/rezepte/ogorki-malosolne), wer stattdessen lange gegorene Gurken für den Winter sucht, findet sie bei den [Ogórki kiszone](/de/rezepte/ogorki-kiszone).', 'Ogórki małosolne scharf | Chili Gurken | Alemniam', 'Scharfe Ogórki małosolne mit Chili und Meerrettich. Bilingual, 2-Prozent-Lake, nicht Essig.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-ogorki-malosolne-ostre', 'pl', 'Ogórki małosolne ostre', 'ostre', 'Ostry wariant korzysta z tej samej łagodnej zalewy 2 procent co klasyczne ogórki małosolne, ale świeże chili i kawałek chrzanu wprowadzają wyraźną ostrość w krótkim czasie kiszenia, bez odrobiny octu.', '[{"text":"Umyj twarde ogórki i przytnij końce, potem ułóż je w słoju z czosnkiem, koperkiem, jedną lub dwiema naciętymi wzdłuż papryczkami chili i kawałkiem korzenia chrzanu.","tip":"To ten sam krótki kis co w [wersji klasycznej](/pl/rezepte/ogorki-malosolne/klasyczne), zmienia się tylko przyprawa, z prawdziwymi [ogórkami kiszonymi](/pl/rezepte/ogorki-kiszone) czy octowymi [ogórkami konserwowymi](/pl/rezepte/ogorki-konserwowe) to nie ma nic wspólnego."},{"text":"Na zalewę wymieszaj 1 litr chłodnej wody z 20 g soli niejodowanej, co daje około 2 procent, przykryj ogórki całkowicie i zostaw w temperaturze 18 do 22 stopni na 24 do 48 godzin, zanim po raz pierwszy spróbujesz.","tip":"Chili i chrzan szybciej aromatyzują zalewę, sama ilość soli się nie zmienia, więcej o technice pisze [poradnik o kiszeniu](/pl/blog/kiszenie-w-domu)."},{"text":"Potem przenieś słoik do lodówki i zjedz ogórki w ciągu dwóch do czterech dni, najlepiej do kiełbasy z grilla i świeżego chleba, a przy pleśni lub nieprzyjemnym zapachu wyrzuć cały słoik.","tip":"Kto woli łagodniej, znajdzie wersję z [miodem](/pl/rezepte/ogorki-malosolne/miod), kto chce więcej chrupkości, wersję z [liściem dębu](/pl/rezepte/ogorki-malosolne/lisc-debu), świeże chili kupisz w markecie, a chrzan często taniej w [sklepie polskim](/pl/blog/sklep-polski-zakupy)."}]'::jsonb, 'Ogórki małosolne ostre, ostra linia małosolnych, ze świeżym chili i chrzanem w tej samej łagodnej zalewie. Ostra linia [ogórków małosolnych](/pl/rezepte/ogorki-malosolne) przejmuje całą technikę wersji klasycznej, do słoika trafiają tylko chili i kawałek chrzanu jako przyprawa. Historycznie chrzan w Małopolsce i na południu Polski był i tak stałym elementem wielu kiszonek, bo jego ostrość i garbniki działają przeciw bakteriom gnilnym, a ogórkom dają mocniejszy, bardziej ziemisty ton, świeże papryczki chili są za to dodatkiem nowszym, który trafił do domowych przepisów wraz z szerszą dostępnością chili w polskich marketach. W przeciwieństwie do octowych [ogórków konserwowych](/pl/rezepte/ogorki-konserwowe) kwas nadal powstaje tu wyłącznie przez fermentację mlekową, chili zmienia jedynie smak, a nie samą technikę czy logikę trwałości. Tak jak w wersji podstawowej okno czasowe zostaje krótkie, jeden do trzech dni w temperaturze pokojowej, bo właśnie to krótkie okno odróżnia małosolne od długo kiszonych [ogórków kiszonych](/pl/rezepte/ogorki-kiszone).

## Zakupy i gotowanie

Kup te samo twarde, świeże małe ogórki co do wersji klasycznej, do tego jedną lub dwie świeże papryczki chili, kawałek korzenia chrzanu, czosnek i koper. Chili dostaniesz zwykle w markecie, sól niejodowaną i chrzan czasem pewniej znajdziesz w [sklepie polskim](/pl/blog/sklep-polski-zakupy).

Zalewa w 2 procentach zostaje identyczna jak w wersji klasycznej, bo chili nie zmienia samej fermentacji mlekowej, dostarcza tylko kapsaicynę odpowiedzialną za ostrość, a nie dodatkowy kwas czy trwałość. Papryczki chili nacięte wzdłuż oddają ostrość do zalewy szybciej niż całe, dlatego ten wariant często smakuje wyraźnie ostrzej już po 24 godzinach niż łagodna wersja bazowa. Tak jak zawsze ogórki muszą zostać całkowicie pod zalewą, a gdy tylko nabiorą lekkiej, okrągłej kwaskowatości z wyczuwalną ostrością, przenieś je do lodówki, inaczej i ten wariant powoli przechyli się w stronę mocniejszych kiszonych.

W Niemczech ten wariant przygotujesz tak samo szybko jak klasyczny, gdy tylko latem w markecie albo w [sklepie polskim](/pl/blog/sklep-polski-zakupy) pojawią się świeże małe ogórki i chili. Dzieci mogą pomagać przy układaniu czosnku i koperku, nacinanie chili i przygotowanie zalewy zostaje przy dorosłych. Gdy brakuje korzenia chrzanu, pomogą [zamienniki składników](/pl/blog/zamienniki-skladnikow).

## Przy stole

Podawaj ostre ogórki do kiełbasy z grilla albo wyrazistych wędlin, ich ostrość dobrze przełamuje tłuste mięso z rusztu. Kto woli łagodniej, znajdzie wariant z [miodem](/pl/rezepte/ogorki-malosolne/miod), wersja klasyczna zostaje przy [ogórkach małosolnych klasycznych](/pl/rezepte/ogorki-malosolne/klasyczne).

Za dużo chili na raz robi zalewę nieprzyjemnie piekącą, a nie przyjemnie ostrą, tu lepiej zachować umiar i dołożyć więcej przy następnym słoiku. Zwiększanie ilości soli z powodu chili jest zbędne, bo ostrość pochodzi z kapsaicyny, a nie z soli. A kto myli ten wariant z octowymi [ogórkami konserwowymi](/pl/rezepte/ogorki-konserwowe), oczekuje złej trwałości i złego poziomu kwasu.

Kto chce jeszcze ostrzej, bierze dwie papryczki chili zamiast jednej albo zostawia w nich pestki, kto woli okrągło i słodko, przechodzi do wariantu z [miodem](/pl/rezepte/ogorki-malosolne/miod) albo do szczególnie chrupiącego wariantu z [liściem dębu](/pl/rezepte/ogorki-malosolne/lisc-debu). Wszystkie trzy dzielą klasyczną bazę [ogórków małosolnych](/pl/rezepte/ogorki-malosolne), a kto szuka długo kiszonych ogórków na zimę, znajdzie je w [ogórkach kiszonych](/pl/rezepte/ogorki-kiszone).', 'Ogórki małosolne ostre | Chili | Alemniam', 'Ostre ogórki małosolne z chili i chrzanem. Dwujęzycznie, zalewa 2 procent, nie ocet.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
